const n = b.c.length;
const out = new Array(n).fill(null);
const up = new Array(n).fill(null);
const dn = new Array(n).fill(null);
const fin = function (x) { return typeof x === 'number' && x === x && x !== Infinity && x !== -Infinity; };
let period = Math.floor(Number(p && p.period));
if (!fin(period) || period < 1) period = 14;
let band = Number(p && p.band);
if (!fin(band)) band = 1;
band = Math.abs(band);
let cumPV = 0, cumV = 0, cumTP = 0, cumN = 0;
let atr = null, trSum = 0, trCount = 0;
let prevClose = null;
for (let i = 0; i < n; i++) {
  const h = Number(b.h[i]), l = Number(b.l[i]), c = Number(b.c[i]);
  const newDay = (i === 0) || (b.day && b.day[i] !== b.day[i - 1]);
  if (newDay) { cumPV = 0; cumV = 0; cumTP = 0; cumN = 0; }
  if (!fin(h) || !fin(l) || !fin(c)) { continue; }
  const tp = (h + l + c) / 3;
  let vol = b.v ? Number(b.v[i]) : 0;
  if (!fin(vol) || vol < 0) vol = 0;
  cumPV += tp * vol;
  cumV += vol;
  cumTP += tp;
  cumN += 1;
  let vwap = null;
  if (cumV > 0) vwap = cumPV / cumV;
  else if (cumN > 0) vwap = cumTP / cumN;
  const tr = (prevClose === null)
    ? (h - l)
    : Math.max(h - l, Math.abs(h - prevClose), Math.abs(l - prevClose));
  if (atr === null) {
    trSum += tr;
    trCount += 1;
    if (trCount === period) atr = trSum / period;
  } else {
    atr = (atr * (period - 1) + tr) / period;
  }
  prevClose = c;
  if (atr !== null && fin(atr) && atr > 0 && vwap !== null && fin(vwap)) {
    const d = (c - vwap) / atr;
    if (fin(d)) { out[i] = d; up[i] = band; dn[i] = -band; }
  }
}
return { VWAP_ATR: out, UPPER: up, LOWER: dn };
